/*@lib*/
let body = $('Summary webhook').first().json.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch { body = null; } }
if (!body || typeof body !== 'object') body = {};
const period = ['day', 'week', 'month', 'year'].includes(body.period) ? body.period : 'week';
const back = Number.isInteger(body.back) && body.back >= 0 && body.back < 1000 ? body.back : 0;
const dayVs = body.dayVs === 'prev' ? 'prev' : 'week', broken = body.broken === true;
const latest = $('Latest report').first().json.latest;
if (!latest?.report) return [{ json: { none: true, key: '' } }];
const report = latest.report, now = new Date();
const figs = report.clients.map(c => ({ c, f: periodFigures(c.client, { ...c, asOf: report.asOf }, period, now, back, dayVs) }));
const f = figs[0].f, named = periodWords(period, back, dayVs, f.from);
const aiInput = buildAiInput(figs.map(({ c, f }) => ({ client: c.client, name: c.name, kpis: f.kpis, previousKpis: f.before, warnings: f.health.warnings })), named);
const aiBody = { messages: [{ role: 'system', content: "You write the results summary that a marketing agency's account manager reads before sending reports to two clients. Use plain, friendly English. Never type a digit. Wherever a number goes, write a placeholder from that client's \"placeholders\" list in curly braces, exactly as named, for example {costPerLead}. Code replaces each placeholder with the value listed next to it, so you can see what the reader will see. Never calculate new numbers. Use only the placeholders of the client you are writing about. The overview covers both clients and has no numbers or placeholders. Placeholders ending in _change already say which way it went (for example \"up 5%\" or \"down 33%\"): write \"leads were {leads_change} compared with <period.vs>\", never \"leads rose {leads_change}\". Outside the curly braces, never write field names such as costPerLead or paidLeads; say \"cost per lead\" or \"paid leads\". The input's \"period\" says what the data covers (\"covers\", for example \"this month so far\") and what every change compares with (\"vs\"): use exactly those words for them and never name any other time (no \"last week\" or \"last month\" unless that is what they say). The value next to each placeholder is what the reader sees, so the word after a count must agree with it: \"{orders} order\" only when the value is 1, \"{orders} orders\" for any other value. When period.finished is false the period is still under way: say \"so far\". Keep each summary to two or three sentences: say what matters most in this period and why, using only the few numbers that support it. Do not list every number; the dashboard shows them all. Write one item per warning: start it with that warning's {<code>_message} placeholder (the check's own sentence, numbers included), then add one short sentence in client-friendly words on what it means, with no numbers. For example \"{duplicates_message} Some people filled in the form twice, so the lead count looks better than it is.\" Never retype a number from a warning's message; the placeholder shows it. Suggest at most three practical next steps per client. Every placeholder needs its own label within a few words of it, in the same sentence, like these examples. A placeholder without its label nearby, or right after another number's label, makes the answer invalid.\n{spend}: next to \"spend\" or \"spent\" or \"budget\", e.g. \"ad spend was {spend}\"\n{leads}: next to \"lead\" or \"enquiry\" or \"enquiries\", e.g. \"{leads} leads came in\"\n{paidLeads}: next to \"paid lead\" or \"from ads\" or \"from paid\", e.g. \"{paidLeads} paid leads\"\n{costPerLead}: next to \"per lead\" or \"per paid lead\" or \"each lead\" or \"each paid lead\", e.g. \"cost per paid lead was {costPerLead}\"\n{cancelled}: next to \"cancel\" or \"refund\", e.g. \"{cancelled} cancelled bookings\"\n{bookings}: next to \"booking\" or \"booked\" or \"consultation\" or \"appointment\", e.g. \"{bookings} booked consultations\"\n{costPerBooking}: next to \"per booking\" or \"each booking\" or \"per consultation\" or \"per appointment\", e.g. \"cost per booking was {costPerBooking}\"\n{bookingRate}: next to \"rate\" or \"of leads\" or \"of all leads\", e.g. \"a booking rate of {bookingRate}\"\n{orders}: next to \"order\" or \"purchase\", e.g. \"{orders} orders\"\n{revenue}: next to \"revenue\" or \"sales\" or \"income\", e.g. \"revenue was {revenue}\"\n{roas}: next to \"return on ad spend\" or \"roas\", e.g. \"return on ad spend was {roas}\"\n{costPerOrder}: next to \"per order\" or \"each order\", e.g. \"cost per order was {costPerOrder}\"\n{avgOrderValue}: next to \"average order\" or \"order value\", e.g. \"the average order was {avgOrderValue}\"\nA {name_change} placeholder needs the same label as {name}, e.g. \"leads were {leads_change} compared with <period.vs>\" or \"cost per lead was {costPerLead_change}\".\nA {code_message} placeholder is the check's own sentence: put it on its own, e.g. \"{duplicates_message}\". Stay inside the length limits, counted after the placeholders are filled in: overview one sentence under 200 characters, headline under 90, summary under 600, each warning under 300, each next step under 200. Return JSON that matches the schema exactly. 'clinic' is the clinic, 'store' is the store." }, { role: 'user', content: JSON.stringify(aiInput) }],
  response_format: { type: 'json_schema', json_schema: { name: 'summary', strict: true, schema: AI_SCHEMA } } };
// a period under way changes as the day goes on: kept for the hour (or until the run's data changes)
const at = !f.current ? '' : f.cut ? f.asOf : f.asOf.slice(0, 13);
const key = [latest.runId, period, f.from, f.to, dayVs, at].join('|');
const out = { period: named, from: f.from, to: f.to, current: f.current, asOf: f.asOf };
return [{ json: { key, broken, aiInput, aiBody, out } }];

const fx = $('Figures').first().json, row = $input.first().json;
const overLimit = (row.today ?? 0) >= 40;
// the broken-answer test skips any kept answer (it would hide the test) and never needs the AI: its reply is replaced anyway
const cached = fx.broken ? null : row.body ?? null;
return [{ json: { cached, overLimit, needAi: !fx.none && !cached && !fx.broken && !overLimit } }];

/*@lib*/
const fx = $('Figures').first().json;
return [{ json: { ok: !!pickAiAnswer($input.all().map(i => i.json), fx.aiInput).value } }];

/*@lib*/
const fx = $('Figures').first().json, d = $('Decide AI').first().json;
if (fx.none) return [{ json: { code: 404, save: false, body: { error: 'There is no report yet: run the report first.' } } }];
if (d.cached) return [{ json: { code: 200, save: false, body: { ...d.cached, cached: true } } }];
// the demo's "broken AI answer": the reply is a refusal, which the checks turn down, so the template writes
const replies = fx.broken ? [{ statusCode: 200, body: { choices: [{ message: { content: "Sorry, I can't help with that." } }] } }]
  : ['AI: write summary', 'AI: second try'].filter(n => $(n).isExecuted).flatMap(n => $(n).all().map(i => i.json));
const pick = pickAiAnswer(replies, fx.aiInput);
const why = pick.value ? null : d.overLimit ? 'the demo’s AI allowance for today is used up' : fx.broken ? 'the AI’s answer was a refusal, so the checks turned it down'
  : pick.gotAnswer ? `the AI’s answer failed the checks (${pick.errors[0]})` : `the AI didn’t answer (${pick.errors[0] ?? 'no reply'}); try again in a minute`;
const body = { ...fx.out, source: pick.value ? 'ai' : 'template', why, value: pick.value ?? templateSummary(fx.aiInput) };
return [{ json: { code: 200, save: body.source === 'ai', body } }];
